import{_ as t,o,c as a,a2 as n}from"./chunks/framework.CZo9GF0W.js";const p=JSON.parse('{"title":"MongoDB and Atlas","description":"","frontmatter":{},"headers":[],"relativePath":"recipes/mongodb.md","filePath":"recipes/mongodb.md","lastUpdated":1789060268000}'),d={name:"recipes/mongodb.md"};function s(r,e,i,l,c,h){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="mongodb-and-atlas" tabindex="-1">MongoDB and Atlas <a class="header-anchor" href="#mongodb-and-atlas" aria-label="Permalink to &quot;MongoDB and Atlas&quot;">​</a></h1><h2 id="atlas" tabindex="-1">Atlas <a class="header-anchor" href="#atlas" aria-label="Permalink to &quot;Atlas&quot;">​</a></h2><p>Atlas hands you an SRV URI. Paste it into the host field and Pitta fills the form from it.</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Scheme</td><td><code>mongodb+srv:// (Atlas)</code></td></tr><tr><td>Host</td><td><code>cluster0.abcde.mongodb.net</code> — no port; SRV resolves the host list from DNS</td></tr><tr><td>Database</td><td>the database to open, e.g. <code>orders</code></td></tr><tr><td>Username</td><td>the database user, not your Atlas account</td></tr><tr><td>Auth source</td><td><code>admin</code> — the usual answer for an Atlas user, and the setting that most often causes &quot;authentication failed&quot;</td></tr><tr><td>TLS</td><td>on, implied by SRV</td></tr><tr><td>Environment</td><td><code>prod</code> if it is</td></tr></tbody></table><p>Add your address to the project&#39;s <strong>Network Access</strong> list. Under Remote-SSH, that is the remote&#39;s egress address, not your laptop&#39;s.</p><p>An SRV URI implies TLS and cannot be tunnelled — see below.</p><h2 id="a-replica-set-by-seed-list" tabindex="-1">A replica set by seed list <a class="header-anchor" href="#a-replica-set-by-seed-list" aria-label="Permalink to &quot;A replica set by seed list&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Scheme</td><td><code>mongodb://</code></td></tr><tr><td>Host + Port</td><td>the first member</td></tr><tr><td>Additional hosts</td><td>the others, as <code>host:port</code></td></tr><tr><td>Replica set</td><td><code>rs0</code></td></tr><tr><td>Read preference</td><td><code>primary</code> for editing; <code>secondaryPreferred</code> for a reporting profile</td></tr></tbody></table><p>Pitta probes the topology at connect and refines the session&#39;s capabilities from what it finds. A <strong>standalone</strong> server has no transactions, so the grid&#39;s apply dialog says the batch cannot be rolled back and reports which edits landed, rather than promising an atomicity that deployment does not provide.</p><h2 id="a-single-local-container" tabindex="-1">A single local container <a class="header-anchor" href="#a-single-local-container" aria-label="Permalink to &quot;A single local container&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Scheme</td><td><code>mongodb://</code></td></tr><tr><td>Host</td><td><code>localhost</code>, port <code>27017</code></td></tr><tr><td>Database</td><td><code>test</code></td></tr><tr><td>TLS</td><td>off</td></tr><tr><td>Direct connection</td><td>on, if the container advertises a hostname you cannot resolve</td></tr></tbody></table><p><strong>Direct connection</strong> tells the driver to talk to exactly this host and not to follow the topology it is told about. It is the fix for a containerised replica set that advertises internal names.</p><h2 id="authentication-mechanisms" tabindex="-1">Authentication mechanisms <a class="header-anchor" href="#authentication-mechanisms" aria-label="Permalink to &quot;Authentication mechanisms&quot;">​</a></h2><p>SCRAM is the default and needs nothing said. x509 uses the client certificate and key from the TLS section, with no username. AWS IAM authentication is supported for Atlas.</p><p>Kerberos and LDAP are <strong>not</strong> available: they need native modules, and Pitta ships one platform-neutral VSIX rather than a build per platform. The same choice excludes client-side field-level encryption.</p><h2 id="tunnels" tabindex="-1">Tunnels <a class="header-anchor" href="#tunnels" aria-label="Permalink to &quot;Tunnels&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">An SRV or seed-list connection refuses an SSH tunnel</p><p>The driver discovers the other members after it connects, and those addresses only resolve on the bastion&#39;s side. One forwarded port cannot serve them, and honouring the tunnel for the seed and then bypassing it for the rest would look like it worked. A <strong>standalone</strong> server tunnels normally.</p><p>Use a VPN, or attach VS Code to a machine inside the network. See <a href="./ssh">the SSH recipe</a>.</p></div><h2 id="what-you-will-see" tabindex="-1">What you will see <a class="header-anchor" href="#what-you-will-see" aria-label="Permalink to &quot;What you will see&quot;">​</a></h2><p><strong>Fields are inferred from a sample.</strong> A collection has no declared schema, so the tree, the grid&#39;s columns and the completion index all come from sampling documents — the sample size is on the profile. Every suggestion says where it came from. A field present only in rare documents may not appear until you widen the sample.</p><p><strong>Missing is not null.</strong> A document that lacks a field shows a distinct token, not <code>NULL</code>, and clearing a cell asks which you meant: set it to null, or <code>$unset</code> it.</p><p><strong>Types stay exact.</strong> <code>Decimal128</code> is a string end to end, <code>Int64</code> is a <code>bigint</code>, and an <code>ObjectId</code> exports as an <code>ObjectId</code> rather than as <code>{}</code>.</p><p><strong>Sampling reads your data.</strong> The inference and the completion index read real documents. Both stay in the extension host and obey the metadata cache TTL, and neither is sent anywhere.</p><h2 id="guards-worth-knowing" tabindex="-1">Guards worth knowing <a class="header-anchor" href="#guards-worth-knowing" aria-label="Permalink to &quot;Guards worth knowing&quot;">​</a></h2><ul><li><code>deleteMany({})</code> and <code>updateMany({})</code> are treated as DML with no <code>WHERE</code> and are blocked by <code>pitta.query.blockUnqualifiedDml</code>.</li><li>An aggregation containing <code>$out</code> or <code>$merge</code> is classified as a write, found by walking the pipeline rather than by trusting the method name.</li><li><code>.mongodb.js</code> files are <strong>parsed, never evaluated</strong>. No <code>eval</code>, no <code>vm</code>, no <code>new Function</code>.</li><li>Server-side JavaScript — <code>$where</code>, <code>$function</code>, <code>$accumulator</code>, <code>mapReduce</code> — is refused unless explicitly enabled and is always an admin operation.</li><li><code>readOnly</code> on a MongoDB profile is <strong>client-side only</strong> and says so. The server-side equivalent is a user granted only <code>read</code>.</li></ul><h2 id="things-that-look-like-bugs" tabindex="-1">Things that look like bugs <a class="header-anchor" href="#things-that-look-like-bugs" aria-label="Permalink to &quot;Things that look like bugs&quot;">​</a></h2><ul><li><strong>Authentication failed with the right password.</strong> Auth source. Atlas users authenticate against <code>admin</code>, not against the database you are opening.</li><li><strong><code>getaddrinfo ENOTFOUND</code> on an SRV host.</strong> SRV needs DNS <code>SRV</code> and <code>TXT</code> lookups, which some corporate resolvers and some container DNS setups drop.</li><li><strong>Connects, then times out on every operation.</strong> The seed resolved but the advertised member hostnames did not. Turn <strong>Direct connection</strong> on, or fix the advertised names.</li></ul>',26)])])}const m=t(d,[["render",s]]);export{p as __pageData,m as default};
